import ast
import os

def get_docstring(node):
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        doc = ast.get_docstring(node)
        return doc.split('\n')[0].strip() if doc else ""
    return ""

def get_clean_signature(node):
    # node is FunctionDef or AsyncFunctionDef
    prefix = "async " if isinstance(node, ast.AsyncFunctionDef) else ""
    # Get the full signature using unparse and strip 'def' and ':'
    full_sig = f"{prefix}{ast.unparse(node)}"
    clean_sig = full_sig.replace("def ", "").split(":")[0].strip()
    return clean_sig

def process_module(filepath, module_name):
    with open(filepath, "r", encoding="utf-8") as f:
        tree = ast.parse(f.read())

    lines = [f"## paket.{module_name}"]

    # 1. Modül düzeyindeki sabitler (Assign)
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and not target.id.startswith("_"):
                    doc = get_docstring(node).replace("\n", " ")
                    lines.append(f"- `{target.id}` — {doc}")

    # 2. Modül düzeyindeki fonksiyonlar (FunctionDef / AsyncFunctionDef)
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith("_"):
                sig = get_clean_signature(node)
                doc = get_docstring(node).replace("\n", " ")
                lines.append(f"- `{sig}` — {doc}")

    # 3. Sınıflar ve metotları (ClassDef)
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            if not node.name.startswith("_"):
                doc = get_docstring(node).replace("\n", " ")
                lines.append(f"- `class {node.name}` — {doc}")
                # Sınıf metotları
                for item in node.body:
                    if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if not item.name.startswith("_"):
                            sig_part = get_clean_signature(item)
                            doc_method = get_docstring(item).replace("\n", " ")
                            lines.append(f"- `{node.name}.{sig_part}` — {doc_method}")

    return lines

all_output = []
for filename in sorted(os.listdir("paket")):
    if filename.endswith(".py"):
        # __init__.py boşsa atla kuralı
        path = os.path.join("paket", filename)
        if filename == "__init__.py" and os.path.getsize(path) == 0:
            continue

        # _ ile başlayan modüller belgelenmez (kural: "Adı _ ile başlayan modüller... belgelenmez")
        # Ancak __init__.py hariç tutulmuş olabilir mi? Kural: "__init__.py dosyası boşsa atla." 
        # Diğerleri için "_ ile başlayanlar" kuralı geçerli.
        if filename.startswith("_") and filename != "__init__.py":
            continue

        module_name = filename.replace(".py", "")
        module_lines = process_module(path, module_name)
        all_output.append("\n".join(module_lines))

with open("API.md", "w", encoding="utf-8") as f:
    f.write("\n\n".join(all_output))

